import { Injectable } from '@angular/core';
import { HttpClient, HttpResponse } from '@angular/common/http';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  constructor(private http: HttpClient) {}

  authenticate(formData: any): Observable<boolean> {
    return new Observable<boolean>((observer) => {
      this.http
        .post<HttpResponse<any>>('http://localhost:8080/user/login', formData, {
          observe: 'response',
        })
        .subscribe({
          next: (response) => {
            if (response.status === 200) {
              console.log('Login successful');
              observer.next(true);
              observer.complete();
            } else {
              observer.next(false);
              observer.complete();
            }
          },
          error: (error) => {
            console.error('Login error', error);
            observer.next(false);
            observer.complete();
          },
        });
    });
  }
}
